bodies.coverageStrip:
const u = warns.find(x => x.code === "unattributed_content");
if(!u) return "";
const m = /^(\d+)%/.exec(u.message || "");
return ` <span class="src" id="coverage">unattributed content: ${
  m ? `<b>${esc(m[1])}%</b> of the document lies outside every item`
    : esc(u.message)
} — interior gaps are not counted, so true non-coverage can be up to 9.7 points higher (ADR-019 §d)</span>`;
